const volumeArtKey=code=>'volume-'+(/^[A-Z]$/.test(code)?'upper-':'lower-')+code;
const uniqueArtCaption=e=>e.kind==='place'?'AI 油画 · 地点艺术演绎，非历史实景':e.kind==='person'?'AI 油画 · 人物艺术演绎，非原作肖像':'AI 油画 · 群体主题艺术演绎';
atlasEntries.forEach(e=>{const key='unique-'+e.id;artwork[key]={file:'assets/unique/'+e.id+'.jpg',title:e.name,credit:uniqueArtCaption(e)};e.image=key});
chapters.filter(c=>c.code).forEach(c=>{let key=volumeArtKey(c.code);artwork[key]={file:'assets/unique/'+key+'.jpg',title:c.title,credit:'AI 油画 · 本卷主题艺术演绎'}});
const immersionChapterArtOriginal=chapterArt;
chapterArt=c=>c.code?volumeArtKey(c.code):immersionChapterArtOriginal(c);
entryVisual=function(e,cls=''){return `<figure class="atlas-art ${cls}"><img src="${entryImage(e)}" alt="${esc(e.name)} · 独立生成的内容插图" loading="lazy"><figcaption>${esc(uniqueArtCaption(e))}</figcaption></figure>`};
image=function(e){let found=atlasEntries.find(a=>a.name===e[0]||a.terms.includes(e[0]));return found?entryVisual(found,e[2]==='人物'?'portrait-plate':'place-plate'):plate('library')};
const immersionSlotsOriginal=insertedPictures;
insertedPictures=function(c){let slots=immersionSlotsOriginal(c),used=new Set();for(let [pos] of slots){let candidates=atlasEntries.filter(e=>e.matches.some(m=>m.chapter===c.id&&Math.abs(m.pos-pos)<7)&&!used.has(e.id));let e=candidates.find(e=>e.kind==='place')||candidates[0];slots.set(pos,e?e.image:chapterArt(c));if(e)used.add(e.id)}return slots};
function realWorldLinks(e){if(e.kind!=='place')return '';const query=encodeURIComponent(e.en+', Paris, France');const mapUrl=e.lat?`https://www.google.com/maps/search/?api=1&query=${e.lat}%2C${e.lon}`:`https://www.google.com/maps/search/?api=1&query=${query}`;return `<div class="real-world-links"><p>Retrouver le lieu · 看看今天的巴黎</p><a href="${mapUrl}" target="_blank" rel="noopener noreferrer">Google 地图 ↗</a>${e.lat?`<a href="https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${e.lat}%2C${e.lon}" target="_blank" rel="noopener noreferrer">附近街景 ↗</a><a href="https://www.openstreetmap.org/?mlat=${e.lat}&mlon=${e.lon}#map=18/${e.lat}/${e.lon}" target="_blank" rel="noopener noreferrer">OpenStreetMap ↗</a>`:''}<small>${e.lat?'链接打开当代地图；附近街景是否可用由地图服务决定。':'此档案尚无可靠坐标，仅提供地名检索；搜索结果不等同于历史旧址。'}</small></div>`}
const immersionPanelOriginal=showAtlasPanel;
showAtlasPanel=function(e){immersionPanelOriginal(e);if(e?.kind==='place')document.querySelector('.atlas-panel-body')?.insertAdjacentHTML('beforeend',realWorldLinks(e))};
const immersionDossierOriginal=dossierPage;
dossierPage=function(id){let e=atlasById.get(id),html=immersionDossierOriginal(id);if(!e)return html;return html.replace('<section class="dossier-records">',`${realWorldLinks(e)}<section class="dossier-records">`).replace('<div class="dossier-hero',`<p class="french-marginalia">${e.kind==='place'?'Mémoire des pierres · 城市的肌理':e.kind==='person'?'Visages du siècle · 世纪的面孔':'Figures de la foule · 人群的身影'}</p><div class="dossier-hero`)};
let paintedMapMode='painted',mapTime='twilight',tourTimer=null,tourIndex=0;
const immersionAtlasPageOriginal=atlasPage;
atlasPage=function(){return immersionAtlasPageOriginal().replace('<div class="atlas-toolbar">',`<div class="scene-mode-bar"><div role="group" aria-label="地图显示方式"><button data-scene-mode="painted" aria-pressed="${paintedMapMode==='painted'}">Paris peint · 油画漫游</button><button data-scene-mode="geographic" aria-pressed="${paintedMapMode==='geographic'}">Carte réelle · 现实地图</button></div><div class="scene-day-controls"><button data-day="day" aria-pressed="${mapTime==='day'}">Jour · 日光</button><button data-day="twilight" aria-pressed="${mapTime==='twilight'}">Crépuscule · 暮色</button><button id="start-walking-tour">开始漫游</button></div></div><div class="atlas-toolbar">`).replace('<div class="map-viewport"',`<div id="geographic-map" class="geographic-map" ${paintedMapMode==='geographic'?'':'hidden'}></div><div class="map-viewport"`).replace('<div class="map-base">',`<div class="painted-city-layer"><img src="assets/unique/painted-paris-map.jpg" alt="巴黎建筑与塞纳河的油画鸟瞰，艺术演绎，非测绘图"></div><div class="map-base">`).replace('油画示意底图 · 现存地标坐标仅供索引','油画鸟瞰与实景地图 · 双层城市索引')};
function geographicEmbed(e){let lat=e?.lat||48.863,lon=e?.lon||2.341;return `https://www.openstreetmap.org/export/embed.html?bbox=${lon-.02}%2C${lat-.012}%2C${lon+.02}%2C${lat+.012}&layer=mapnik&marker=${lat}%2C${lon}`}
function refreshScene(){const el=document.querySelector('#geographic-map'),view=document.querySelector('#map-viewport');if(!el||!view)return;el.hidden=paintedMapMode!=='geographic';view.hidden=paintedMapMode==='geographic';view.dataset.time=mapTime;document.querySelectorAll('[data-scene-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sceneMode===paintedMapMode)));document.querySelectorAll('[data-day]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.day===mapTime)));let e=atlasById.get(atlasState.selected);if(e?.kind!=='place')e=e?.related.map(r=>atlasById.get(r.id)).find(p=>p?.lat);if(paintedMapMode==='geographic'){let url=geographicEmbed(e);if(el.dataset.source!==url){el.dataset.source=url;el.innerHTML=`<iframe src="${url}" title="OpenStreetMap 现实地理位置" loading="lazy" referrerpolicy="no-referrer"></iframe><p>当代地图 · © OpenStreetMap contributors · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">数据署名</a>。需联网加载。</p>`}}}
const immersionUpdateAtlasOriginal=updateAtlas;
updateAtlas=function(){immersionUpdateAtlasOriginal();refreshScene()};
function stopWalkingTour(){if(tourTimer){clearInterval(tourTimer);tourTimer=null}const b=document.querySelector('#start-walking-tour');if(b){b.textContent='开始漫游';b.setAttribute('aria-pressed','false')}}
function tourStep(){if(document.body.classList.contains('motion-off'))return;const stops=atlasEntries.filter(e=>e.kind==='place'&&e.lat);const e=stops[tourIndex++%stops.length];atlasState.selected=e.id;atlasState.kind='all';atlasState.query='';const input=document.querySelector('#atlas-search');if(input)input.value='';if(!matchMedia('(prefers-reduced-motion: reduce)').matches){let p=projected(e),view=document.querySelector('#map-viewport');atlasState.zoom=1.35;atlasState.x=(50-p.x)*view.clientWidth/100;atlasState.y=(50-p.y)*view.clientHeight/100}updateAtlas()}
function bindImmersiveMap(){document.querySelectorAll('[data-scene-mode]').forEach(b=>b.onclick=()=>{paintedMapMode=b.dataset.sceneMode;refreshScene()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{mapTime=b.dataset.day;refreshScene()});let b=document.querySelector('#start-walking-tour');if(b)b.onclick=()=>{if(tourTimer){stopWalkingTour();return}b.textContent='停止漫游';b.setAttribute('aria-pressed','true');tourStep();tourTimer=setInterval(tourStep,9000)};refreshScene()}
const immersionRenderOriginal=render;
render=function(){stopWalkingTour();immersionRenderOriginal();const [route,id]=decodeURI(location.hash.slice(1)).split('/');if(route==='atlas')bindImmersiveMap();if(route==='read'){let c=bookById.get(id);document.querySelector('.reading-title')?.insertAdjacentHTML('afterbegin',`<span class="french-volume-label">${c?.code?'Cahier '+esc(c.code):'Les manuscrits'} · Archives de Paris</span>`)}if(route==='sources')document.querySelector('.section')?.insertAdjacentHTML('beforeend','<h2>独立图像与实景入口</h2><p>36个卷轴与92份地点、人物、群体档案分别生成专属插画。生成肖像与旧址画面均为艺术演绎，不是考证依据。油画鸟瞰用于氛围；现实位置请切换OpenStreetMap，或使用地点档案中的Google地图及附近街景链接。街景呈现当代环境，服务可用性和覆盖范围由地图服务决定。</p>');document.querySelector('.paris-colophon')?.remove();document.querySelector('footer')?.insertAdjacentHTML('afterbegin','<div class="paris-colophon"><span>Paris, capitale du XIXe siècle</span><em>Fragments · Passages · Visages</em></div>')};
document.querySelector('#app').addEventListener('pointermove',e=>{if(e.pointerType==='touch'||matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('motion-off'))return;let view=e.target.closest('.map-viewport');if(view&&!view.classList.contains('dragging')){let r=view.getBoundingClientRect();view.style.setProperty('--scene-x',((e.clientX-r.left)/r.width-.5)*9+'px');view.style.setProperty('--scene-y',((e.clientY-r.top)/r.height-.5)*7+'px')}});
document.querySelector('#app').addEventListener('pointerdown',e=>{if(e.target.closest('.map-viewport,[data-atlas-select]'))stopWalkingTour()});
removeEventListener('hashchange',immersionRenderOriginal);addEventListener('hashchange',render);render();
const immersionFinalRender=render;
render=function(){let [route,id]=decodeURI(location.hash.slice(1)).split('/');if(route==='group'){let keys=['flaneur','ragpicker','collector','clerk','gambler','sexworker'];if(keys[+id])history.replaceState(null,'','#dossier/group-'+keys[+id])}immersionFinalRender()};
removeEventListener('hashchange',immersionFinalRender);addEventListener('hashchange',render);render();
